/* Linker version script for the C ABI shared library: export only the public
   nemo_speech_asr_* / nemo_speech_diar_* symbols; hide everything else (the linked-in C++
   implementation). */
{
    global:
        nemo_speech_asr_*;
        nemo_speech_diar_*;
    local:
        *;
};
